<script lang="ts">
  import type { Snippet } from 'svelte'; import type { HTMLIframeAttributes } from 'svelte/elements'; import { cn } from '../../utils.js'; import { sanitizePreviewUrl, useWebPreviewContext } from './context.svelte.js';
  interface Props extends Omit<HTMLIframeAttributes, 'class' | 'src' | 'srcdoc' | 'sandbox' | 'title' | 'onload' | 'loading'> { src?: string; srcdoc?: string; sandbox?: string; title?: string; loading?: Snippet; class?: string; onload?: (event: Event) => void; }
  let { src, srcdoc, sandbox, title, loading, class: className = '', onload, ...rest }: Props = $props(); const preview = useWebPreviewContext('WebPreviewBody'); const resolvedSrc = $derived(src === undefined ? preview.safeUrl : sanitizePreviewUrl(src)); const resolvedSrcdoc = $derived(srcdoc ?? preview.srcdoc); const resolvedSandbox = $derived(sandbox ?? preview.sandbox);
  function loaded(event: Event): void { preview.frameLoaded(); onload?.(event); }
</script>
<div class="svadmin-ai-web-part__body" data-slot="web-preview-body">{#if preview.loading}{#if loading}{@render loading()}{:else}<span class="svadmin-ai-web-part__loading" role="status">Loading preview...</span>{/if}{/if}{#if resolvedSrc || resolvedSrcdoc}{#key preview.revision}<iframe {...rest} class={cn('svadmin-ai-web-part__frame', className)} src={resolvedSrc || undefined} srcdoc={resolvedSrcdoc} sandbox={resolvedSandbox} title={title ?? preview.title} onload={loaded}></iframe>{/key}{:else}<p>No preview URL.</p>{/if}</div>
